#include <iostream>
#include <iomanip>
#include <utility>

int encrypt(int number) {
    int d1 = (number / 1000) % 10;
    int d2 = (number / 100) % 10;
    int d3 = (number / 10) % 10;
    int d4 = number % 10;

    d1 = (d1 + 7) % 10;
    d2 = (d2 + 7) % 10;
    d3 = (d3 + 7) % 10;
    d4 = (d4 + 7) % 10;

    std::swap(d1, d3);
    std::swap(d2, d4);

    return d1 * 1000 + d2 * 100 + d3 * 10 + d4;
}

int decrypt(int number) {
    int d1 = (number / 1000) % 10;
    int d2 = (number / 100) % 10;
    int d3 = (number / 10) % 10;
    int d4 = number % 10;

    std::swap(d1, d3);
    std::swap(d2, d4);

    // Using (d + 3) % 10 to invert (d + 7) % 10 safely without negative numbers
    d1 = (d1 + 3) % 10;
    d2 = (d2 + 3) % 10;
    d3 = (d3 + 3) % 10;
    d4 = (d4 + 3) % 10;

    return d1 * 1000 + d2 * 100 + d3 * 10 + d4;
}

int main() {
    int inputNumber = 0;
    if (std::cin >> inputNumber) {
        int encrypted = encrypt(inputNumber);
        int decrypted = decrypt(encrypted);

        std::cout << "Original:  " << std::setw(4) << std::setfill('0') << inputNumber << "\n";
        std::cout << "Encrypted: " << std::setw(4) << std::setfill('0') << encrypted << "\n";
        std::cout << "Decrypted: " << std::setw(4) << std::setfill('0') << decrypted << "\n";
    }
    return 0;
}

#include <iostream>
#include <iomanip>

int main() {
    const double initialPopulation = 8.0; // In billions
    const double growthRate = 0.0105;     // 1.05% annual rate
    double currentPopulation = initialPopulation;
    int doublingYear = 0;

    std::cout << std::left << std::setw(6) << "Year"
              << std::setw(20) << "End-of-Year Pop(B)"
              << std::setw(18) << "Increase (B)" << "\n";
    std::cout << "--------------------------------------------\n";
    std::cout << std::fixed << std::setprecision(4);

    for (int year = 1; year <= 5; ++year) {
        double increase = currentPopulation * growthRate;
        currentPopulation += increase;

        if (doublingYear == 0 && currentPopulation >= 2.0 * initialPopulation) {
            doublingYear = year;
        }

        std::cout << std::left << std::setw(6) << year
                  << std::setw(20) << currentPopulation
                  << std::setw(18) << increase << "\n";
    }

    // Continue simulation through year 75 to find doubling year
    for (int year = 6; year <= 75; ++year) {
        double increase = currentPopulation * growthRate;
        currentPopulation += increase;

        if (doublingYear == 0 && currentPopulation >= 2.0 * initialPopulation) {
            doublingYear = year;
        }
    }

    std::cout << "--------------------------------------------\n";
    std::cout << "Population doubles at year: " << doublingYear << "\n";
    return 0;
}
